.calendar {
    width: 300px;
    padding: 16px;
    box-sizing: border-box;
    user-select: none;
}

.calendar__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
}

.calendar__title {
    text-transform: capitalize;
}

.calendar__grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 2px;
}

.calendar__weekday {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 32px;
}

.calendar__day {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 36px;
    border: none;
    border-radius: var(--g-border-radius-m, 6px);
    background: transparent;
    cursor: pointer;
    font: inherit;
    font-size: 14px;
    color: var(--g-color-text-primary);
    transition: background-color 0.15s ease;
}

.calendar__day:hover {
    background: var(--g-color-base-simple-hover);
}

.calendar__day_outside {
    color: var(--g-color-text-hint);
}

.calendar__day_today {
    font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--g-color-line-brand);
}

.calendar__day_selected,
.calendar__day_selected:hover {
    background: var(--g-color-base-brand);
    color: var(--g-color-text-inverted-primary);
}

.calendar__footer {
    display: flex;
    justify-content: flex-end;
    margin-top: 12px;
}

